pages.css:
.content-root{width:100%;height:100%;padding:18px 20px;overflow:hidden;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#ffffff;}
.consonants-header{margin-bottom:24px;text-align:center;}
.consonants-header h2{font-size:32px;font-weight:800;color:#E2571C;text-transform:uppercase;letter-spacing:2px;margin:0 0 12px;}
.caps-toggle{display:flex;justify-content:center;gap:0;margin-top:4px;}
.caps-btn{padding:8px 22px;font-size:16px;font-weight:800;border:2px solid #dee2e6;background:#fff;color:#1a1a1a;cursor:pointer;transition:all .15s;border-radius:20px;}
.caps-btn:first-child{border-radius:20px 0 0 20px;}
.caps-btn:last-child{border-radius:0 20px 20px 0;border-left:none;}
.caps-btn.active{background:#E2571C;border-color:#E2571C;color:#fff;}
.caps-btn:not(.active):hover{background:#f5f7fa;}
.consonants-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:14px;width:100%;max-width:820px;padding:10px;justify-items:center;align-items:center;}
.letter{width:80px;height:80px;border:3px solid #dee2e6;border-radius:20px;background:#fff;font-size:38px;font-weight:800;color:#1a1a1a;cursor:pointer;transition:all .15s ease;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 8px rgba(0,0,0,.08);}
.letter:hover{border-color:#F5A623;transform:scale(1.06);box-shadow:0 6px 14px rgba(0,0,0,.12);}
.letter:active{transform:scale(0.95);}

pages.js:
const letters = document.querySelectorAll('.letter');
const colors = ['#1a1a1a','#ff0000','#ff7f00','#ffff00','#00ff00','#0000ff','#4b0082','#9400d3'];
const stateMap = new Map();
letters.forEach(letter => {
  letter.addEventListener('click', () => {
    const key = letter.dataset.letter;
    const cur = stateMap.get(key) || 0;
    const next = (cur + 1) % colors.length;
    letter.style.color = colors[next];
    stateMap.set(key, next);
  });
});

// Caps Toggle
const capsBtns = document.querySelectorAll('.caps-btn');
capsBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    capsBtns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const isUpper = btn.dataset.case === 'upper';
    letters.forEach(letter => {
      const orig = letter.dataset.letter;
      letter.textContent = isUpper ? orig.toUpperCase() : orig.toLowerCase();
    });
  });
});

